dimensions.script:
def content = params._source['content'];
if (content == null || !content.containsKey('commands')) return "N/A";

def commands = content['commands'];
if (commands == null || commands.isEmpty()) return "N/A";

def firstCommand = commands[0];
if (firstCommand == null || !firstCommand.containsKey('recordingSegment')) return "N/A";

def recordingSegment = firstCommand['recordingSegment'];
if (recordingSegment == null || !recordingSegment.containsKey('segmentParticipantInfos')) return "N/A";

def segmentInfos = recordingSegment['segmentParticipantInfos'];
if (segmentInfos == null || segmentInfos.isEmpty()) return "N/A";

def agentIds = new ArrayList();
for (item in segmentInfos) {
  if (item != null && item['type'] == 'AGENT' && item.containsKey('userId') && item['userId'] != null) {
    agentIds.add(item['userId']);
  }
}

return agentIds.isEmpty() ? "N/A" : String.join(",", agentIds);

